code.cpp:
class Solution {
public:
    int minOperations(vector<string>& logs) {
        int depth = 0;
        for (const string& op : logs) {
            if (op == "../") {
                if (depth > 0) --depth;
            } else if (op == "./") {
                // stay in the same folder, do nothing
            } else {
                // move into a child folder
                ++depth;
            }
        }
        return depth;
    }
};
